package archive

import (
	"bytes"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"testing"

	"campfire/internal/shared/model"
)

func TestDecodersRejectOversizedDictionariesBeforeAllocation(t *testing.T) {
	// Independent fixtures are generated by Python, not these decoders.
	fixture := func(name string) []byte {
		t.Helper()

		data, err := os.ReadFile(filepath.Join("testdata", "valid."+name))
		if err != nil {
			t.Fatal(err)
		}

		return data
	}
	xzData := fixture("tar.xz")

	blockSize := (int(xzData[12]) + 1) * 4
	if xzData[13] != 0 || xzData[14] != 0x21 || xzData[15] != 1 {
		t.Fatal("unexpected XZ fixture filters")
	}

	xzData[16] = 38 // 2 GiB dictionary, reject before the decoder allocates it.
	binary.LittleEndian.PutUint32(xzData[12+blockSize-4:], crc32.ChecksumIEEE(xzData[12:12+blockSize-4]))

	lzipData := fixture("tar.lz")

	lzipData[5] = 28 // 256 MiB dictionary.
	for _, item := range []struct {
		format model.ArchiveFormat
		data   []byte
	}{
		{model.ArchiveTarXZ, xzData},
		{model.ArchiveTarLzip, lzipData},
		{model.ArchiveTarZstd, []byte{0x28, 0xb5, 0x2f, 0xfd, 0x00, 0x98, 0x01, 0x00, 0x00}},
	} {
		t.Run(string(item.format), func(t *testing.T) {
			reader, err := newTarReader(t.Context(), bytes.NewReader(item.data), int64(len(item.data)), item.format)
			if err == nil {
				_, err = reader.Next()
				_ = reader.Close()
			}

			if !errors.Is(err, errDecoderMemory) {
				t.Fatalf("expected dictionary/window limit, got %v", err)
			}
		})
	}
}

func TestLzipValidatesEveryTrailerFieldAndTruncation(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "valid.tar.lz"))
	if err != nil {
		t.Fatal(err)
	}

	for _, offset := range []int{20, 16, 8} {
		damaged := bytes.Clone(data)
		damaged[len(damaged)-offset] ^= 0xff

		reader, err := newLzipReader(bytes.NewReader(damaged))
		if err != nil {
			t.Fatal(err)
		}

		if _, err = io.Copy(io.Discard, reader); err == nil {
			t.Fatal("corrupt trailer accepted", offset)
		}
	}

	for length := range len(data) {
		reader, err := newLzipReader(bytes.NewReader(data[:length]))
		if err == nil {
			_, err = io.Copy(io.Discard, reader)
		}

		if err == nil || (length > 0 && errors.Is(err, io.EOF)) {
			t.Fatal("truncated member accepted", length, err)
		}

		if length > 0 {
			reader, err := newLzipReader(bytes.NewReader(append(bytes.Clone(data), data[:length]...)))
			if err != nil {
				t.Fatal(err)
			}

			if _, err := io.Copy(io.Discard, reader); err == nil {
				t.Fatal("truncated later member accepted", length)
			}
		}
	}

	reader, err := newLzipReader(bytes.NewReader(append(bytes.Clone(data), data...)))
	if err != nil {
		t.Fatal(err)
	}

	decoded, err := io.ReadAll(reader)
	if err != nil || len(decoded) != 20480 {
		t.Fatal("concatenated lzip members failed", len(decoded), err)
	}
}
